mapper.select:
SELECT * FROM (
	SELECT chat_num, group_num, member_num, member_nick, 1 AS state, message AS "value", created_at
	FROM group_chat WHERE group_num = #{group_num}

		AND chat_num < #{before_chat_num}

	ORDER BY created_at DESC, chat_num DESC
)
WHERE ROWNUM <= 100
ORDER BY created_at ASC, chat_num ASC
